## Server-Sent Events in Next.js

## SSE Message Format

```
Text stream over HTTP, each message ends with \n\n

event: notification          (optional: event type)
id: 42                       (optional: for reconnection)
data: {"text":"New reply"}   (required: payload)
                             (empty line = end of message)

// Event without type (default 'message' event)
data: {"progress": 75}

// Heartbeat / keep-alive
: this is a comment, keeps connection alive
```

## Route Handler Implementation

```typescript
// app/api/notifications/stream/route.ts
export async function GET(req: Request) {
  const { searchParams } = new URL(req.url);
  const userId = searchParams.get('userId')!;

  const stream = new ReadableStream({
    async start(controller) {
      const encoder = new TextEncoder();

      const send = (event: string, data: unknown) => {
        controller.enqueue(
          encoder.encode(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`),
        );
      };

      // Send initial state
      send('connected', { userId, timestamp: Date.now() });

      // Subscribe to Redis pub/sub for this user's notifications
      const subscriber = redis.duplicate();
      await subscriber.subscribe(`notifications:${userId}`, (message) => {
        send('notification', JSON.parse(message));
      });

      // Heartbeat every 30s to prevent proxy timeout
      const heartbeat = setInterval(() => {
        controller.enqueue(encoder.encode(': heartbeat\n\n'));
      }, 30_000);

      // Cleanup on disconnect
      req.signal.addEventListener('abort', async () => {
        clearInterval(heartbeat);
        await subscriber.unsubscribe();
        await subscriber.quit();
        controller.close();
      });
    },
  });

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache, no-transform',
      Connection: 'keep-alive',
      'X-Accel-Buffering': 'no', // Disable Nginx buffering
    },
  });
}
```

## Client-Side

```typescript
function useNotifications(userId: string) {
  const [notifications, setNotifications] = useState<Notification[]>([]);

  useEffect(() => {
    const es = new EventSource(`/api/notifications/stream?userId=${userId}`);

    es.addEventListener('notification', (e) => {
      setNotifications(prev => [JSON.parse(e.data), ...prev]);
    });

    es.onerror = () => {
      // EventSource auto-reconnects after error
      console.warn('SSE connection lost, reconnecting...');
    };

    return () => es.close();
  }, [userId]);

  return notifications;
}
```

